<div class="sl-head"><div><h1 class="sl-title">Shipping Tariffs</h1><p class="sl-lede">Air is priced by weight (lb). Sea is priced by space (cubic feet). Each band applies to a route; customer-specific rates override the general ones.</p></div><div class="row g8 wrap"><a class="sl-btn ghost" href="<?= sl_route('QuoteCalculator') ?>"><i class="ic ic-sm i-eye" aria-hidden="true"></i>Customer view</a><a class="sl-btn ghost" href="<?= h(sl_url(['export' => 'csv'])) ?>"><i class="ic ic-sm i-download" aria-hidden="true"></i>Export rate card</a><?php if ($d['canAdd']): ?><a class="sl-btn" href="<?= sl_route('RateEditor') ?>"><i class="ic ic-sm i-plus" aria-hidden="true"></i>Add rate</a><?php endif; ?></div></div>
<form method="get" class="row g8"><div class="sl-search" style="max-width:360px"><i class="ic ic-sm i-search" aria-hidden="true"></i><input name="q" value="<?= h($d['q']) ?>" aria-label="Search tariffs" placeholder="Search country, state, city or customer"></div></form>
<?php if (!$d['groups']): ?><div class="sl-empty"><span class="sl-tile"><i class="ic i-tag" aria-hidden="true"></i></span>No tariffs<?= $d['q'] !== '' ? ' match this search' : ' yet' ?>.<?php if ($d['canAdd']): ?> <a href="<?= sl_route('RateEditor') ?>">Add the first rate</a>.<?php endif; ?></div><?php endif; ?>
<div class="grid cols2" style="align-items:start">
<?php foreach ($d['groups'] as $m => $g): ?>
<section class="tf-mode<?= $g['sea'] ? ' sea' : '' ?>"><div class="tf-hd"><span class="tf-ic"><i class="ic <?= $g['sea'] ? 'i-ship' : 'i-plane' ?>" aria-hidden="true"></i></span><div class="grow"><h2 class="sl-ct"><?= h($g['name']) ?></h2><div class="mut sm"><?= (int) $g['n'] ?> band<?= $g['n'] === 1 ? '' : 's' ?></div></div></div>
<div class="tf-k"><div><small>From</small><b><?= h($g['from']) ?></b><span class="mut sm">lowest band</span></div><div><small>Up to</small><b><?= h($g['to']) ?></b><span class="mut sm">highest band</span></div><div><small>Volume divisor</small><b><?= (int) $g['vol'] ?></b><span class="mut sm"><?= $g['sea'] ? 'L×W×H in ÷ 1,728' : 'L×W×H ÷ divisor' ?></span></div></div>
<div class="sl-tw"><table class="sl-table"><thead><tr><th><?= $g['sea'] ? 'Space' : 'Weight band' ?></th><th>Route</th><th class="num">Price</th><th class="num">Min charge</th><th></th></tr></thead><tbody><?php foreach ($g['rows'] as $r): ?><tr><td class="fw5"><?= h($r['band']) ?><?php if ($r['client']): ?><span class="sub">for <?= h($r['client']) ?></span><?php endif; ?></td><td class="sm"><?= h($r['route']) ?><?php if ($r['valid']): ?><span class="sub"><?= h($r['valid']) ?></span><?php endif; ?></td><td class="num"><?= h($r['price']) ?><span class="sub"><?= h($r['mile']) ?></span></td><td class="num"><?= h($r['min']) ?></td><td><span class="row g4"><?php if ($d['canEdit']): ?><a class="sl-ib sm" aria-label="Edit band <?= h($r['band']) ?>" href="shipping_tariffs_edit.php?id=<?= (int) $r['id'] ?>"><i class="ic i-edit" aria-hidden="true"></i></a><?php endif; ?><?php if ($d['canDelete']): ?><button class="sl-ib sm" aria-label="Delete band <?= h($r['band']) ?>" data-sl-action="ajax/sl/tariff_save_ajax.php" data-p-op="delete" data-p-id="<?= (int) $r['id'] ?>" data-sl-confirm="Delete this rate band?" data-sl-reload><i class="ic i-trash" aria-hidden="true"></i></button><?php endif; ?></span></td></tr><?php endforeach; ?></tbody></table></div>
<div class="mut sm">Charged on the higher of actual weight or volume weight.</div></section>
<?php endforeach; ?>
</div>
<?php if ($d['custom']): ?><section class="sl-card flush"><div class="row between wrap g8" style="padding:14px 16px"><div><h2 class="sl-ct">Customer-specific rates</h2><div class="mut sm">From the custom fee table; they replace the general band for that customer</div></div></div>
<div class="sl-tw"><table class="sl-table"><thead><tr><th>Customer</th><th>Mode</th><th>Band</th><th class="num">Price</th></tr></thead><tbody><?php foreach ($d['custom'] as $c): ?><tr><td class="fw5"><?= h($c['client']) ?></td><td><?= h($c['mode']) ?></td><td class="mono sm"><?= h($c['band']) ?></td><td class="num"><?= h($c['price']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php if ($d['flat']): ?>
<section class="sl-card col g12" id="price-check"><div class="sl-ch" style="margin:0"><div><h2 class="sl-ct">Price check</h2><div class="mut sm">Pick a mode and type a weight or volume to see the price from the bands above</div></div><div class="row g6" id="tf-modes"><?php foreach ($d['modes'] as $i => $m): ?><button type="button" class="tf-chip <?= $i === 0 ? 'on' : '' ?>" data-m="<?= (int) $m['m'] ?>" data-unit="<?= h($m['unit']) ?>"><?= h($m['label']) ?></button><?php endforeach; ?></div></div>
<div class="grid cols2" style="align-items:start"><div class="tf-q"><label class="sl-field"><span class="sl-lab" id="tf-qlab">Weight (<?= h($d['modes'][0]['unit']) ?>)</span><input class="tf-in" id="tf-qty" value="5" inputmode="decimal"></label><label class="sl-field"><span class="sl-lab">Declared value</span><input class="tf-in" id="tf-val" value="100" inputmode="decimal"></label></div>
<div class="sl-kv" id="tf-lines"></div></div></section>
<script>
(function(){var rows=<?= json_encode($d['flat']) ?>,ins=<?= json_encode($d['insurance']) ?>,sym=<?= json_encode($d['symbol']) ?>,mode=<?= (int) $d['modes'][0]['m'] ?>,unit=<?= json_encode($d['modes'][0]['unit']) ?>;
function f(n){return sym+n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
function esc(s){var e=document.createElement('span');e.textContent=s;return e.innerHTML;}
function calc(){var q=parseFloat(document.getElementById('tf-qty').value)||0,v=parseFloat(document.getElementById('tf-val').value)||0,band=null;rows.forEach(function(r){if(r.m===mode&&q>=r.from&&q<=r.to&&!band)band=r;});
var out=document.getElementById('tf-lines');if(!band){out.innerHTML='<div><span>No band covers '+q+' '+unit+'</span><span>—</span></div>';return;}
var fr=Math.max(q*band.p,band.min||0),i=v*ins/100;out.innerHTML='<div><span>Band</span><span>'+esc(band.route)+'</span></div><div><span>Freight '+q+' '+unit+' × '+f(band.p)+(band.min?' (min '+f(band.min)+')':'')+'</span><span>'+f(fr)+'</span></div><div><span>Insurance '+ins+'%</span><span>'+f(i)+'</span></div><div><span class="fw5">Total</span><span class="fw5 mono" style="font-size:18px">'+f(fr+i)+'</span></div>';}
document.getElementById('tf-modes').addEventListener('click',function(e){var b=e.target.closest('[data-m]');if(!b)return;mode=+b.dataset.m;unit=b.dataset.unit;this.querySelectorAll('[data-m]').forEach(function(x){x.classList.toggle('on',x===b);});document.getElementById('tf-qlab').textContent=(unit==='lb'?'Weight':'Volume')+' ('+unit+')';calc();});
document.getElementById('tf-qty').addEventListener('input',calc);document.getElementById('tf-val').addEventListener('input',calc);calc();})();
</script>
<?php endif; ?>
